INSERT INTO "Titles" (id, name, slug, cover, description, thesis, age_restriction, first_release, lit_form, is_compilation, is_featured) VALUES
  (1, 'Игра в Маяки', 'igra-v-mayaki', 'segamegadrive.png', 'Недалёкое будущее. g, в прошлом художник-акционист, а в настоящем гик-учёный Лаборатории Параллельных Алгоритмов НИИ «Случайный Лес», решает создать уникальную социальную сеть «Маяки», сервера которой не будут под контролем властей мировых государств. Постепенно всё больше и больше людей оказываются вовлечены в реализацию его задумки. Для управления таким масштабным проектом нужен источник нечеловеческой, почти мистической силы. В его поиск включаются как случайные люди, так и таинственные сильные игроки, готовые бросить вызов создателю Игры. На что пойдёт каждый из них, чтобы победить? И как в этом помогут сновидения? Нить размышлений о будущем человечества, ищущего смысл бытия в виртуальных мирах, проведëт вас по лабиринту метафизической, социальной и политической Игры в Маяки. Автор о книге: «Иногда меня увлекает мысль, что между двумя явлениями, кажущимися абсолютно не сопряжёнными, всегда можно найти нечто общее. Роман "Игра в Маяки" освещает эту идею: люди, никак на первый взгляд не связанные, на поверку оказываются близкими родственниками; объекты виртуального мира в известной онлайн-игре подлежат комбинации, чтобы переродиться в новое, никем ещё не изведанное устройство; сновидение становится частью яви, чем явь подтверждает свою причастность к сновидению. Все эти эффекты неожиданного родства вещей и явлений и есть Игра в Маяки. Как, впрочем, и само это рассуждение об Игре в Маяки».', 'Во власти алгоритмов', 18, '2026', 'роман', false, false),
  (2, 'Архив барона Унгерна', 'baron', 'baron.jpg', 'Важнейший исторический документ тысячелетия, окутанный невиданных масштабов ворохом слухов, легенд и домыслов, считался безвозвратно утерянным. Однако же в окне блеснул надежды луч, когда рука Судьбы донесла до редакции Чтива этот исторический роман-фантасмагорию . В сопроводительном письме было сказано, что авторы не раз предлагали его всевозможным издательствам (как выяснилось позже, на протяжении 15(!) лет), но всё это время череда роковых случайностей и мистических происшествий мешала его публикации. Ознакомившись с текстом, Совет Чтива единогласно решил, что мы просто обязаны восстановить историческую справедливость.', 'История о самой истории', 18, '2018', 'Роман', false, false),
  (3, 'На земле Заратуштры', 'na-zemle-zaratushtry', 'na-zemle-zaratushtry.jpg', 'Возвращаться в город детства из-за печальных событий — непросто, даже являясь «взрослой собой». Но что, если возвращаться придётся не только в собственный дом, но и к собственным воспоминаниям? В них — пёстрые рыбы, в них — сады и реки, в них — ушедшее детство; вокруг, в настоящем, — безжизненная пустыня. Героиня отправляется в прошлое, чтобы обрести собственное будущее. Удастся ли ей это? И кем же на самом деле был Заратуштра? Автор о книге: «Одним из источников вдохновения при написании повести послужила катастрофа на Аральском море, которая входит в число самых масштабных экологических проблем Узбекистана по сей день. Так, в произведении главное место действия — вымышленный город в районе Аралкума (пустыни, образовавшейся на месте Аральского моря). Повествование затрагивает два временных отрезка — время до наступления экологической катастрофы и настоящее время, когда Приаралье практически полностью превратилось в пустыню. Моей основной задачей при создании повести было столкнуть две реальности: настоящую, которая представлена в длительных последствиях аральской катастрофы, и вымышленную, мифическую, показанную читателю через отношения духов и богов, живущих в этих краях. Сложно сказать, как именно у меня возникла идея написать эту книгу: с одной стороны, мне хотелось запечатлеть несколько личных историй в вымышленном сеттинге; с другой — показать миру ту часть востока, о которой пока мало где можно узнать. Идеи я собирала отовсюду: так в книге появился знаменитый «Бык» из музея Савицкого в Нукусе, каракалы и степные лисы, красавицы-пери и мальчик по имени Заратуштра. Всё это и часть моей настоящей жизни, и часть того сказочного мира, который я продолжаю создавать в своих работах».', 'На границе двух миров', 12, '2024', 'повесть', false, false),
  (4, 'Трое в лодке', 'troe-v-lodke-ne-schitaya-harona', 'troe-v-lodke-ne-schitaya-harona.png', 'Кто-то назовёт Эдуарда интеллектуалом, добрым человеком и хорошим другом. Другие увидят в нём легкомысленного бездаря и выпивоху. Он идёт по жизни без цели, часто не выбирая средств. Может, бес вселился в него? На короткой ноге с сатанистами, да и сборник своих стихов окрестил «Книгой бесов». Иннокентий Харин по кличке Кельт, тот самый, что назовёт беспутного писателя «хорошим другом», сам похож на заблудшую овцу. Никто толком не знает, чем конкретно он занимается и насколько большая тень лежит на его прошлом и предпринимательской деятельности. Скажи мне, кто твой друг, и я скажу, кто ты. Любимая женщина, та самая, что назовёт Эдуарда «добрым человеком», похожа на Мону Лизу. Она юна и прекрасна, но никто не знает, кто она и что ждать от этого чудесного создания. Что объединяет этих людей? Воспоминания, тёплые чувства или просто река времени, уходящая в царство мёртвых? Драки, внезапные смерти и другой хаос на фоне смены времён и власти — под обложкой казуального романа Эдуарда Диа Диникина о российской действительности, где герои не стремятся к подвигам, но пускаются в авантюры.', 'С плота Лозы в ладью, плывущую по Стиксу нулевых', 18, '2026', 'роман', false, false),
  (5, 'Серебро', 'serebro', 'serebro.png', 'Действие романа начинается в&nbspПетербурге 1913 года — в период, когда реальность бурлила предреволюционными процессами, идеи сталкивались с&nbspидеями в словесных баталиях, после претворялись в дела — и&nbspсталкивались уже на улицах. Известные представители Серебряного века, такие как Хлебников, Бурлюк, Брюсов, Белый, Тиняков, Волошин, пьют в&nbspресторанах, читают свои и чужие тексты и выбрасывают рукописи, которые попадают в&nbspруки чекистов и агентов охранки. Поначалу произведение Эдуарда Диникина напоминает историко-литературный роман, но&nbspреальность оказывается двулика: в мире, где&nbspна&nbspглазах простых смертных меняются вековечные устои, на поверхность прорывается обратная сторона. Известный поэт здесь может оказаться вампиром или прорицателем, случайный телефонный звонок — связать друг&nbspс другом людей из разных эпох, а дешёвый медальон — оказаться волшебным&nbspталисманом. Границы между сном и явью, литературой и действительностью, добром и&nbspзлом оказываются зыбкими и проницаемыми в мире магического реализма, в&nbspкотором у&nbspкаждого свой шорох за спиной.', 'Слово — серебро, молчание — свинец', 18, '2022', 'роман', false, false),
  (6, 'Повелитель блох', 'povelitel-bloh', 'povelitel-bloh.png', 'Представьте, что у вас есть оккультный двойник. Вы ходите на работу, готовите ужин, гуляете с близкими и даже не подозреваете, что в тот же момент ваш двойник восседает на троне из цветочных лепестков или сопровождает принцессу стрекоз. Что вы чувствуете? Погрузитесь в эти ощущения, отправившись в фантастическое путешествие вместе с «Повелителем блох». Иронический роман-приключение, где всё оказывается не тем, чем кажется. Ребёнок увидит в нём рождественскую сказку с волшебными героями, подросток ─ хлёсткую сатиру на общество, а взрослый вспомнит, что в жизни всегда есть место чуду. Неожиданные физические и душевные метаморфозы, говорящие насекомые, подставные расследования, воскрешение принцесс ─ в последнем романе Эрнста Т. А. Гофмана.', 'Чудо исполнилось, мгновение настало', 12, '2023', 'сказочный роман', false, false),
  (7, 'Дочь греха', 'doch-greha', 'doch-greha.png', 'Харизматичный и любвеобильный музыкант и поэт, пагубное пристрастие которого меняет в его жизни всё. Ромео и Джульетта времён Великой Отечественной войны. Взволнованный школьник, испытавший первое вожделение. Профессор и аспирантка, одержимые любовью. Плотские утехи, мимолётные романы, дружеские знакомства, житейская мудрость, девчачьи хитрости, остроумные афоризмы героев и отголоски войны. Всё это и не только ждёт вас под одной обложкой трагикомедийной лёгкой прозы Бориса Майнаева о дамских угодниках, жаждущих любви женщинах и их жизненных перипетиях. Автор о книге: «О чём громко и открыто не говорят или говорят, опуская глаза. В этих рассказах и повестях сладкий флирт незаметно перетекает в горечь трагедии. Любовь и ложь… Страсть и стыд… Жизнь и смерть… Что это — бесконечное обретение познания или бессмыслица, границы которой очерчены не нами?»', 'СЕМЬ МГНОВЕНИЙ СЛАДОСТРАСТИЯ', 18, '2024', 'сборник повестей и рассказов', false, false),
  (8, 'Сверхдержава', 'sverhderzhava', 'sverhderzhava.jpg', 'Воин запаса Бедович ищет своё место в мирной жизни: днём продаёт телевизоры, ночами пробует себя в литературе. Всё круто меняется при знакомстве с писателем, фантомасом и основателем издательства Чтиво Сергеем Иннером, который вскоре психоделически исчезает. Бедович вынужден стать его преемником в таинственной арт-конгрегации Русский Динозавр и сладить с хаосом, который тот оставил после себя. Сознание Бедовича, а с ним и явь начинают меняться, люди всё чаще принимают за Иннера его самого. Роман с бывшей любовницей Иннера, сердцеедкой доктором-кардиологом превращается в абьюзивный цикл на стыке жизни, смерти и русской киберпанк-апокалиптики: кровососущие банкиры доводят общество до тотальной нищеты и массового помешательства, мутирующие от царь-вируса полицейские становятся зомби, а массолит бесконтрольно рождает тысячи плохих книг глупых писателей. Или всё это лишь художественное произведение Бедовича? Сможет ли герой спасти себя от нищеты, Чтиво от краха, а страну Россию от печальной участи Карфагена? Решает ли простой человек в своей жизни хоть что-нибудь, и чем он должен пожертвовать, чтобы стать непростым? Узнаем ли мы правду о войне с е■учими монголами? И, наконец, сакральное Бедовичево: «Как устроена страна Россия в частности и мир в целом»? Автор о книге: «Сызмальства я мечтал создать экзистенциальный романтический боевик социальной направленности с элементами бурлескного артхаус-порно-триллера для крестьян, рабочих, феминисток, спортсменов, психологов, бизнес-коучей, депутаток, инстабогинь* и всех, кто не входит в этот перечень. Мечты сбываются!» *Пантеон запрещён на территории страны России', 'любовь и власть', 18, '2025', 'роман-превосхождение', false, false),
  (9, 'Гомоза', 'gomoza', 'gomoza.jpg', 'Любовь, драки, похороны и философские разговоры на кухне — всё в уральской провинции, которая становится символом малой родины: вернуться непросто, но и окончательно покинуть невозможно. Ностальгия, отношения отцов и детей, разочарования и погружение в прошлое. Застарелые психологические травмы, поиски смысла жизни, детские обиды и мучительное взросление уже состоявшегося человека. Перед вами история душевного освобождения Егора Гомозина, уставшего от долгого и скучного существования. Автор о книге: «Писать этот роман я решил спонтанно. Читая Булгакова, наткнулся на слово "гомоза", которое меня заворожило. Я не знал, что оно означает, но решил, что гомоза — это некая серая булькающая, вроде лавы, субстанция, представляющая собой неизвестную или слабо изученную форму жизни. Мне захотелось узнать об этой жизни побольше, изучить её, раз никому, кроме меня, до неё не было никакого дела».', 'Время умирать и время воскресать', 18, '2024', 'роман', false, false),
  (10, 'МРД6', 'moguchij-russkij-dinozavr', 'moguchij-russkij-dinozavr.png', 'В начале было Чтиво. Затем родился Русский Динозавр. Вместе они плечом к плечу стоят на защите современной малой прозы, публикуя для вас исключительные произведения. Перед вами все номера ежегодника: каждый год двенадцать избранных публикаций, двенадцать авторов под одной обложкой — итог двенадцати месяцев работы литжурнала. Выпуски также включают рассказы победителей конкурса рок-прозы «Гроза» радио Овердрайв. Держись, читатель, ибо Русский Динозавр воистину могуч!', 'Excelsior!', 18, '2026', 'ежегодник', false, false),
  (11, 'Сега Мега Драйв', 'segamegadrive', 'segamegadrive.png', 'От первого тетриса до консолей виртуальной реальности, от первой затяжки за школой до диджитал-проектов федерального масштаба: история медиахудожника и продюсера, культ молодости, видеоигр и темнеющего рок-н-ролла, тусовки в супермаркете, диджитал-арт, скейт-поэзия, необитничество, техномистика, психоделириумный экшен и бешеное диско под тяжёлый рок между Петербургом, Москвой, Нижним Новгородом и родными экзистенциальными просторами индивидуального и коллективного бессознательного, а также работа сантехником в детском саду в паре с опустившейся рок-звездой — чистейшая грязь. Нажмите «старт».', 'game lover', 18, '2026', 'роман-геймплей', false, false),
  (12, 'Петербургские повести', 'peterburgskie-povesty', 'peterburgskie-povesty.png', 'В Петербурге «всё обман, всё мечта, всё не то, чем кажется». Ночной блеск его главной улицы, Невского проспекта, легко туманит испытующий взгляд, заставляя прохожего свернуть туда, где случай становится судьбой. В одном доме молодого художника преследует образ неизвестного человека, который не желает отпускать, в другом — чиновник-карьерист теряет собственный нос и во что бы то ни стало пытается его вернуть. Влюблённый мелкий дворянин теряет рассудок, о чём свидетельствует тяжёлый плод его страданий — дневник, а бедный титулярный советник видит смысл своей жизни в шинели. Каждая повесть открывает скрытую сторону города — тревожную, таинственную, иногда пугающе правдивую. Мир будто отражён в кривых зеркалах — привычный порядок вещей нарушается, реальность ускользает, непостижимое и безумное обволакивает сознание героев. В сборник вошли повести «Невский проспект», «Нос», «Портрет», «Записки сумасшедшего» и «Шинель».', 'В тени города, который слышит больше, чем говорит', 16, '2025', 'Сборник повестей', false, false),
  (13, 'Мурло', 'murlo', 'murlo.jpg', 'Степан Фёдорович Домрачёв, чудной пятидесятилетний слесарь, приезжает в село забрать вещи умершего дяди. Там у него угоняют «Газель», поэтому уехать из села он не может. Он начинает переворачивать жизнь местных жителей с ног на голову, постепенно лишаясь рассудка. Автор о книге: «"Мурло" — книга о девиациях. Персонажи, в сущности, самые обыкновенные русские люди, с трудом контролирующие свои страсти. И страсти эти так сильно завладевают ими, что порой может показаться, замещают их, становятся на их место, обретая болезненную форму. Как будто вырезается трафарет, в который удаётся пролезть только образу, высеченному страстями, но не душе. В фильме Андрея Тарковского "Сталкер" герой говорит: "То, что они называют страстью, на самом деле не душевная энергия, а лишь трение между душой и внешним миром". "Мурло" — это попытка осознать, что есть вещи более тонко организованные и могущие принести не трафаретное, а объёмное, истинное счастье».', 'Снег, блинчики, усач, истерика', 18, '2021', 'роман', false, false),
  (14, 'Сын греха', 'sin-greha', 'sin-greha.jpg', 'Мальчишки, получившие неожиданный подарок судьбы в виде молодой девушки, сталкиваются с суровой реальностью. Преданный своему делу врач, в очередной раз встречаясь со смертью, узнаёт о предательстве жены. Следователь и журналист расследуют убийство и измену, скрытые за соседской дверью, а разведчик, впервые поддавшись искушению плоти, открывает для себя новую грань между жизнью и смертью. Пагубные страсти, треволнения сердца, мучительные переживания, размышления о том, как любовь может сплотить и погубить, и о том, что в трудные моменты стоит бросить вызов судьбе, — в продолжении «Дочери греха» Бориса Майнаева. Автор о книге: «Обретённая реальность или утраченные иллюзии? Глубокий омут или чистота горного воздуха? Пепел обыденности или ослепительной силы огонь? Любовь — болезненное, но неизбежное чувство, способное изменить судьбы. Каждый рассказ погружает читателя в мир, где любовь и предательство переплетаются, от первого поцелуя до глубоких размышлений о грехе».', 'Десять мгновений сладострастия', 18, '2025', 'сборник рассказов', false, false),
  (15, 'Кубок войны и танца', 'kubok-voiny-i-tanca', 'kubok-voiny-i-tanca.png', 'О мытарствах литератора в современной России: слово, любовь, смерть, духовные прозрения, соцсети, издательства Москвы, горцы Кавказа, боль и исцеление всего мира и намного больше этого. «Книга эта — любовь, должная вращать целый мир, приводить его в движение согласно своим законам, выращенным в уме», — пишет автор.', 'Жизнь вопреки всему', 18, '2019', 'Роман', false, false),
  (16, 'Виски сауэр', 'whiskey-sour', 'whiskey-sour.png', '«Виски сауэр» — инструкция по применению внутрь: Патриков, алкоголя, женского внимания, мужских эмоций, историй в стиле стендап, бесед с бомжами и богачами. Саргис живёт в спальном районе и каждый день оказывается на Патриках как на работе. Разговоры у туалета, за барной стойкой, в чужой квартире, на поле для гольфа, на уличной скамейке. Люди меняются как в калейдоскопе. Тон книги — тон выпившего друга: искренний, грустный, рефлексивный, свой. Градус актуальности и узнаваемости высок, ведь «Виски сауэр» не о вечном, а о хрупком, бытовом, близком. Для тех, кто прислушивается к себе и другим людям, любит хороший рассказ и точность попадания в суть. Тех, кому наскучило «нормальное» и кто хотя бы раз пил алкоголь на последние — просто для того, чтобы остаться собой. Издатели книги не пропагандируют табак, алкоголь, наркотики и насилие, не всегда разделяют увлечения героев и призывают читателей к здоровому образу жизни.', 'Принимать внутрь', 18, '2025', 'роман', false, false),
  (17, 'Кокора', 'kokora', 'kokora.jpg', 'Симон — талантливый писатель. Он создаёт заказную попсу под массой имён, понимая, что его личная реальность — бесконечное противоречие. Творческие амбиции заземлены необходимостью писать ради заработка. Он мечтает об успехе, но рутина литературного «негритянства» откладывает его планы на неопределённый срок. В поисках выхода из этого тупика Симон находит загадочную работу, однако в первый же день всё принимает неожиданный оборот — ему выдают странный шлем. Надев его, Симон превращается в муху и попадает в иллюзорный мир. Балансируя между двумя реальностями, он приступает к своей миссии. Но кто он на самом деле? «Кокора» — многослойный роман, где границы действительности порой стёрты. Личностные перипетии соседствуют с невероятными технологическими идеями и сказочными погружениями в странные миры насекомых.', 'Мысли — это маленькие зелёные человечки. Ты хочешь их воспитать, но у них своё мнение', 18, '2025', 'роман', false, false),
  (18, 'Макинтош для близнецов', 'makintosh-dlya-bliznecov', 'makintosh-dlya-bliznecov.jpg', 'Нина стаскивает Сашу в реальную жизнь прямо со сцены. Обе девушки устали от одиночества, но они непохожи: Нина торгует своим телом, а Саша не может продать Шекспира. Держась друг за друга, как за костыли, две невезучие героини постигают в окружающих и в самих себе душевную инвалидность и шаг за шагом учатся жить. Читатель видит мир глазами обеих: переносится флешбэками в их детство и юность, а затем возвращается в неустроенную и искалеченную жизнь. Амплитуда событий колеблется от омерзительного до возвышенного, вместе девушки бунтуют против пошлости, из которой не могут выбраться сами. Будет ли крик об одиночестве и нежелании жить в грязи услышан? Перед вами повесть о счастье и горестях, о вечном и преходящем, о цинизме и инфантильности, о превозможении и тёмных закоулках человеческой души, где так легко потеряться. Автор о книге: «Это история о необычном человеке, который родился в обычном мире, об инвалидности и целлюлите душ и тел, о поиске безусловной любви, о хроническом одиночестве и рецидивирующей жестокости, о падении и неврозах, о проституции. Книга о том, в чём сегодня запуталось полмира, о том, что ниже пояса, и о том, что выше, — тоже! Ещё о диких розах и людях, о сладкой алыче, о Маркесе, о пьяном немце и о белой полосе в небе, которую оставляет самолёт...»', 'Если ты встретил странного человека — значит, он где-то чудом выжил', 18, '2025', 'повесть', false, false),
  (19, 'Сновидящий и снотворящий', 'snovidyashiy-i-snotvorishiy', 'snovidyashiy-i-snotvorishiy.png', 'Сон на грани реальности. Реальность, утопающая во снах. В этом романе вы познакомитесь с историями повелителя-предсказателя, блогерши-снотворицы, Архитектора и его снотворящего Великана, Героини, которую преследует зловещая Белая Барышня, и даже группировки похитителей&nbsp;снов. Для романа в рассказах характерна особая темпоральность: сновидческое ускорение времени. Авторская пунктуация будто рассекает пространство повествования на два состояния: бодрствование и сон, жизнь и смерть, играет роль «крючьев», за которые цепляются сознания героя и читателя. Автор о книге: «Каждый рассказ романа появился из тщетной попытки вести дневник сновидений. Люди записывают ночные грёзы по разным причинам, мне же хотелось сохранить картинки ускользающих после пробуждения образов. С переменным успехом мне это удавалось, но через какое-то время появилось стойкое желание дополнить и развить отрывочные сновидческие впечатления. Результатом своей литературно-сновидческой работы я хочу поделиться с читателями, а также пригласить их присоединиться к клубу первых в мире сновидцев-книгочеев».', 'ОСТАВЬ НАДЕЖДУ, ВСЯКИЙ ЗАСЫПАЮЩИЙ', 18, '2023', 'роман в рассказах', false, false),
  (20, 'Об пол', 'ob-pol', 'ob-pol.jpg', 'Маус был обычным студентом медицинского вуза, пусть и не подавал особых надежд. Однако автоавария по пути на занятия перечеркнула всю его жизнь, ведь парень лишился ноги из-за тяжёлой травмы. Из глубокой апатии и депрессии его смог вывести лишь Терапевт — загадочный, огромных размеров человек с неожиданными методами работы. Теперь он готов снова выйти в мир, окружающий родной панельный двенадцатиэтажный дом. Однако новым препятствием на его пути внезапно становится сломанный лифт. Поняв, что путь наружу для него закрыт, Маус решает погрузиться в жизни, текущие за дверями разных квартир, ещё не подозревая, к чему это может привести. Готовьтесь к встрече с поэтом-садистом, призраком модного художника, поднебесными бездомными и гильдией жалостливых старух — всё под крышей одного панельного дома.', 'Трагикомедия в двенадцати этажах', 18, '2024', 'роман', false, false),
  (21, 'Посейдень', 'poseiden', 'poseiden.jpg', 'Похождения современного автора в поисках издания, выпивки, женщин и смысла жизни, путешествия автостопом по России, Европе и Грузии. Истории, рок-н-ролл, бесконечность, странствия в пространстве и сознании, парикмахерские, фракталы и звёздная грязь. Прыжок в неизвестность без парашюта, акваланга и цианида в петлице. Держись, читатель!', 'Рок-н-ролл, бесконечность и звёздная грязь', 18, '2017', 'Роман в рассказах и повестях', false, false),
  (22, 'Неслучившееся', 'unhappened', 'unhappened.jpg', 'Ни один из этих рассказов, написанных с 2014 по 2018 год, по словам автора, не был придуман специально — они просто приходили и сами помогали себя написать. И по стилю повествования это заметно: лёгкий слог, плавные сюжетные линии, темпоритм выдержанного арт-хауса. «В жизни так мало сюжета и так много важных мелочей, она так хороша в своей недосказанности» — пишет Даша. «Неслучившееся» случилось в качестве третьей книги Чтива, и мы рады представить вам этот феномен.', 'Такое бывает раз в никогда', 16, '2018', 'Cборник рассказов', false, false),
  (23, 'Времяпадение', 'vremyapadenie', 'vremyapadenie.jpg', 'Дизайнер в поисках вдохновения погружается в симуляцию чужих воспоминаний, стирая границы между своей жизнью и жизнью незнакомки. Отец-одиночка становится оператором тактического дрона, но война, в которой он участвует ради сына, забирает куда больше, чем может вернуть. Решив сообщить дочери о разводе, родители сталкиваются с пугающей правдой: в её жизни их место уже заняла безупречно заботливая машина. В мире, где антропоморфных андроидов преследуют как врагов человечества, семья укрывает беглую девочку-синта, не подозревая, что эта тайна изменит их жизнь навсегда. Десять историй о людях и технологиях, разрушенных городах и надеждах, реальности, подчас неотличимой ото сна — наступает эпоха Времяпадения. Автор о книге: «Все истории этого сборника так или иначе рассказывают о времени и попытках человека противостоять его разрушительной работе. Время — самая страшная и могущественная сила мироздания. Его нельзя приручить, умилостивить, подкупить. Ему безразличны человеческие устремления, сокровенные мечты или боль. Время — убийца, но оно и созидатель. Без времени нет жизни, как нет её и без умирания и распада. Самой нашей вселенной не существовало бы без времени. Оно помогает нам понять себя и трезво оценивать свои поступки и место в обществе, развиваться и крепнуть. Но научиться жить в согласии с ним нелегко. Герои моих историй решают эту проблему по-разному, часто ценой невероятных потерь. Готовых ответов нет — есть только время».', 'ЗАТИШЬЕ ОБМАНЧИВО, БЕЗОПАСНОСТЬ — МИФ, НАДЕЖДА — РОСКОШЬ', 16, '2024', 'сборник рассказов', false, false),
  (24, 'Худшее', 'hudshee', 'hudshee.jpg', 'Годами паблик АХУЛИ (Ассоциация Худших Литераторов) собирал худшие тексты нашего поколения, месяц за месяцем совершенствуя свою худшесть — и теперь, наконец, всё стало так плохо, что на это невозможно смотреть без слёз. Сборник «Худшее» призван довести ситуацию до абсолютной, запредельной, нечеловеческой концентрации худшего из худшего. Составители тщательно отбирали тексты, тестируя их на фокус-группе смертников. Будьте уверены: ни один текст, который своей плохостью не убил хотя бы пару тестировщиков, не вошёл в сборник. Мы искренне рекомендуем поберечь свои нервы и никогда, ни за что не иметь дел с этой книгой. Это может плохо закончиться.', 'Хуже и быть не может', 18, '2023', 'худший сборник прозы и поэзии', false, false),
  (25, 'Город случайностей', 'gorod-sluchajnostej', 'gorod-sluchajnostej.jpg', 'Прежде чем отправиться на прогулку по шести улицам Петербурга Достоевского, усвойте правила выживания. Избегайте резких поворотов. Не ходите за господином с чёрной лентой на шляпе. Не стойте долго у парадных. Не идите в дом на зов музыки, доносящейся из освещённого окна, ведь никогда не знаешь, чем обернётся ваше вторжение. А если покажется, что вы узрели истину, не верьте — вдруг это всего лишь сон. До вас донесутся обрывки разговоров — странных, тайных. Разговоров на грани смеха и слёз. Вас встретят герои случая, поступки которых вы, возможно, поймёте не сразу. Но вчитайтесь и понаблюдайте за ними! Приятной вам прогулки по городу Достоевского — городу случайностей, которые, быть может, не случайны. В сборник вошли рассказы «Честный вор», «Чужая жена и муж под кроватью», «Сон смешного человека», «Скверный анекдот», «Ползунков» и повесть «Вечный муж».', 'Я не то, что вы думаете', 16, '2024', 'сборник прозы', false, false),
  (26, 'Вихрь жизни', 'vihr-zhizni', 'vihr-zhizni.jpg', 'Грешник, оказавшийся во власти тьмы, но способен ли он на раскаяние?.. Распутный пьяница, решивший дать своей жене свободу и шанс на любовь с другим, но какой ценой?.. Господа-самодуры и горничная, решившая их одурачить, но удастся ли ей исхитриться и остаться безнаказанной?.. Прелюбодеяние и ревность, душегубство и угрызения совести. Любовь и ненависть, отчаяние и смелость, судьбы людей и бездушная судебная система. Надменность и праздность, смекалка и надежда на лучшую жизнь, увлечение спиритизмом и земельные вопросы. Две драмы «Власть тьмы» и «Живой труп», а также комедия интриги «Плоды просвещения» Льва Толстого, которые породила сама жизнь.', 'Удивительна слабость человеческая!', 12, '2024', 'сборник пьес', false, false),
  (27, 'Призрачные истории', 'prizrachnye-istorii', 'prizrachnye-istorii.jpg', 'Ужасающе реалистичный сборник произведений, в которых Булгаков-мистик и Булгаков-сатирик вплетает инфернальные мотивы и абсурдистские штрихи в нелёгкую жизнь советского человека. Будьте бдительны: читая эту книгу, вы столкнётесь с дьявольской силой бюрократической машины, станете свидетелем безумного эксперимента и участником спиритического сеанса, встретите покойников и побываете на мероприятии, где происходит чёрт-те что. И вы думаете, что это всё?.. В сборник вошли повести «Дьяволиада», «Роковые яйца», рассказы «Тайна несгораемого шкафа», «Спиритический сеанс», «№ 13. — Дом Эльпит-Рабкоммуна», «Сверхъестественный мальчик», «Как он сошёл с ума», «Как школа провалилась в преисподнюю», «Приключения покойника», «Чертовщина», «Когда мёртвые встают из гробов», «Мёртвые ходят», «Охотники за черепами» и «Сапоги-невидимки». Издание дополняет предисловие Галины Дербиной о мистике в жизни и творчестве Михаила Булгакова. Галина Дербина — автор-исследователь романа «Мастер и Маргарита», булгаковские шарады которой регулярно публикуются в литжурнале Русского Динозавра .', 'Побеждали лучшие и сильные. И эти лучшие были ужасны', 12, '2024', 'сборник прозы', false, false),
  (28, 'Худшее-2', 'hudshee-2', 'hudshee-2.jpg', 'Время собирать тексты, и время разбрасывать худшие из них. Ассоциация Худших Литераторов тщательно отобрала у вас возможность не узнать о них никогда. В прошлом году мы думали, что хуже быть не может. Как же же-же-жестоко мы ошибались! Ходят слухи, что администраторы паблика проводили над авторами бесчеловечные опыты: били их током, Ожеговым и учебником логики, окунали в случайно разлитый одрерир и даже заставляли общаться с техподдержкой некоего банка. Так тексты подопытных стали эсхатологически ужасны и кристально отвратительны. Все специалисты, причастные к работе над сборником, задавались вопросом: «Почему должны страдать только мы одни?!» Исправляем эту несправедливость — теперь любой желающий может разделить нашу боль. Обретайте, скачивайте, приобщайтесь… Но учтите: если вы любите хорошую поэзию, цените своё время и психическое здоровье — эта книга не для вас. Не читайте её. Побойтесь бога, раз уж авторы — не.', 'Вдвое худшéе', 18, '2024', 'ещё более худший сборник прозы и поэзии', false, false),
  (29, 'Amystis', 'amystis', 'amystis.jpg', 'Смутное время. Двум молодым полководцам поручено спасение Москвы от осаждающего её Тушинского вора. Все победы одержаны, враги повержены, и остаётся сделать последний шаг, но герои внезапно замирают перед решающим выбором: а что, если его не делать? Что, если предпочесть подвигам и славе эстетическое созерцание и гомерический абсурдизм?', 'Не доволен окружающим миром — есть другие', 18, '2019', 'роман-анализ', false, false),
  (30, 'Пупсики', 'pupsiki', 'pupsiki.jpg', 'С началом войны шеф-редактор Бедович меняет уют двухкомнатной квартиры на коммунальную реальность и увлекается сожительством с прекрасными юными созданиями из разных городов и общественных страт. В условиях неосознанной подверженности глобальным изменениям общественного сознания, начинаясь как безобидная игра, сюжет выходит на уровень психоэстетического хоррора с элементами вынужденного социокультурного исследования. Узнай, много ли пупсиков вокруг тебя и как любовь к ним может стать фатальной — чти сиквел романа-превосхождения «Сверхдержава» шеф-редактора Чтива.', 'Без зла ты в опасности', 18, '2024', 'повесть', false, false),
  (31, 'Российское время', 'rossijskoe-vremja', 'rossijskoe-vremja.jpg', 'Свобода, любовь и ревность. Митинги, секты, войны и революции. Завал, ущерб, повышение. Пиво, глинтвейн, отвёртка. Кошка, кошечка и Принцесса. Уэлен, ВДНХ, БДСМ. Ёлки, подарки, снеговики, снежинки. Желание жить в тот самый момент.', 'Всё будет', 18, '2019', 'Сборник рассказов и повестей', false, false),
  (32, 'Лежу', 'leshu-neubitiy-zhivoy', 'leshu-neubitiy-zhivoy.png', 'Кто пишет на фронте, да ещё и о любви? Студенты Литинститута имени Горького, оказавшиеся на Советско-финской войне — кто случайно, кто намеренно. Среди снегов, в карельских лесах искусство по-прежнему остаётся главной частью их жизни. Они ищут и находят рифмы, читают стихи в полный голос холодному зимнему небу, но жернова истории норовят перемолоть всех без исключения: Бориса Заходера, Арона Копштейна, Колю Отраду и многих других. Итог сражений хранит прошлое, итог судеб поэтов — повесть Яны Жемойтелите. Автор о книге: «Два года назад на одном библиотечном мероприятии я услышала о студентах литинститута, которые отправились добровольцами на Финскую войну. Они были просто поэтами, мальчишками, которых захватила романтическая идея подвига во имя Родины. Их гибель представилась мне до того несправедливой, что мне захотелось каким-то образом изменить прошлое, как бы странно это не звучало. Однако литература даёт нам такую возможность — воссоздать давно отшумевшие события, на некоторое время воскресить мёртвых. Ведь когда мы погружаемся в историю их жизни и смерти, они какое-то время дышат вместе с нами, а значит, живут. Потери Красной Армии во время Советско-финской войны составили почти триста девяносто две тысячи человек из одного миллиона принимавших участие в боевых действиях. Кем были эти люди? Как они попали на войну? За что сражались и как погибли? И почему мы никак не выучим эти горькие уроки истории — вот о чём хотелось мне рассказать».', 'НА ФРОНТЕ ГРОМКО ПЕТЬ ВОСПРЕЩЕНО', 18, '2024', 'повесть', false, false),
  (33, 'Адвент-календарь Чтива', 'advent-calendar', 'advent-calendar.png', 'Окончание новогодних праздников — не повод отказываться от подарков. Чтобы продвигаться по числам нового месяца было круче и дичайше, Чтиво приготовило для тебя январский адвент-календарь. В закрытом Телеграм-канале каждый день будут появляться новые чумовые сюрпризы. Мы собрали для вас целых тридцать и ещё один подарок. Внутри — десяток свежих цифровых изданий, эксклюзивные материалы от авторов, редакции и радио Овердрайв, курсы, приятные скидки и многое другое.', 'печатный журнал о новой культуре', NULL, '2023', 'ежегодник', false, false),
  (34, 'Я есть Россия', 'i-est-rossia', 'i-est-rossia.png', '«Я есть Россия» — творческий эксперимент, попытка создать Россию на художественной основе. В апреле-июле 2023 года Чтиво провело онлайн-событие, посвящённое роману-ритуалу «россия» Андрея Янкуса. Мы собрали материалы о России, окружающей читателей. Результатом конкурса стал сборник, в который вошли присланные ими фото, стихотворения и размышления. Название выбрано путём народного голосования в соцсетях издательства.', 'Один раз увидеть', 18, '2023', 'сборник материалов', false, false),
  (35, 'Абзац', 'abzac-workshop', 'abzac-workshop.png', 'Огромная литературная семья, включающая в себя писателей, читателей, редакторов, корректоров, верстальщиков, издателей, критиков, иллюстраторов и многих других, продолжает существовать несмотря ни на что. Сколько бы ни применяли к ней цензурных кнутов, какими бы ни закармливали пряниками поп-культуры — задушить её пока не удалось никому. А чтобы этого никому не удалось и впредь, мы открываем мастерскую Абзац, призванную объединять любителей литературы и давать им новые знания, навыки, возможности, и, что важнее прочего, — друг друга.', NULL, NULL, '2023', NULL, false, false),
  (36, 'Под солью', 'v-yarosti-i-pod-solyu', 'v-yarosti-i-pod-solyu.jpg', 'Разочарованный романтик отправляется в болезненный трип по ночной Москве — в побеге от друзей-наркоманов и от самого себя. Нервное повествование чередуется флешбэками-воспоминаниями: о передозах знакомых, побегах от полиции, путешествиях по России, а также — злобными рассуждениями об отношениях, одиночестве, борьбе с зависимостями, богемной среде, современном искусстве, войне и литературе. Автор о книге: «"В ярости и под солью" — маленький злой роман, посвящённый самым стигматизированным порокам поколения миллениалов. Когда я писал этот текст, то повторял себе основную идею: "Это должен быть нежный удар читателю по лицу! Только честно: об одиночестве и химической ярости. Не книга, а пугающий визг на окраине"». Издательство «Чтиво» и автор произведения предупреждают, что употребление наркотических веществ влечёт за собой негативные последствия для здоровья. Распространение и хранение психотропных препаратов запрещено законом. Психологическую поддержку при борьбе с зависимостью можно получить бесплатно по телефону 8 800 302 - 73 - 76 в АНО «Нонарко».', 'Мы копаем общую яму', 18, '2023', 'роман', false, false),
  (37, 'Пляска смерти Председателя Томского', 'predsetatel-tomskiy', 'predsetatel-tomskiy.jpg', '1928 год. СССР готовит отправку атомных звездолётов к Сатурну. Ведутся секретные работы по созданию сверхчеловека, способного покорять космические просторы. Руководит проектом Председатель советских профсоюзов М. П. Томский. Однако проект сталкивается с трудностями: Томский кончает жизнь самоубийством. Расследуя его деятельность, чекисты обнаруживают машину по переселению душ. Судьбы героев оказываются тесно связаны с судьбой машины. Побеждая c её помощью смерть, они открывают нечто большее — возможность счастливо прожить свою жизнь.', 'Историю творят отчаянные', 18, '2023', 'роман', false, false),
  (38, 'Локал', 'local_press', 'local_press.jpg', 'Команда журнала рассказывает о людях и сообществах, ‌формирующих новую культуру. ‌local — это место, где таланты ‌в области ‌фотографии, журналистики, ‌литературы, музыки и не только ‌могут открыто ‌рассказывать ‌истории, ‌экспериментировать ‌и делиться идеями. ‌ ‌‌Команда журнала верит в силу локальных сообществ ‌как точки возрождения русского ‌самосознания и самоуважения.', 'печатный журнал о новой культуре', 18, '2023', 'журнал', false, false),
  (39, 'Олеся', 'olesya', 'olesya.png', 'По долгу службы молодой барин, Иван Тимофеевич, приезжает в глухую деревню на окраине Полесья. Там он влюбляется в Олесю — внучку ведьмы. Казалось бы, им не суждено быть вместе, общество не примет их, ведь по поверьям девушка-колдунья принадлежит дьяволу. Однако не всегда то, что представляется нам злом, является таковым и наоборот; и тот, кто считает недобрым другого, сам может скрывать свою безжалостность. Издание дополняют словарные и реальные комментарии, а также предисловие, в котором рассматривается историко-географический контекст повести. Каждую страницу книги сопровождают иммерсивные цветные иллюстрации.', 'От лености сердца до трефовой любви', 12, '2023', 'повесть', false, false),
  (40, 'Невидимый друг', 'nevidimyi-drug', 'nevidimyi-drug.jpg', 'Элю мучают ночные кошмары, где девочку преследует таинственный монстр. Но всё меняется, когда Эля находит в лесу портал в сказочный мир Виль-Мажин. Там она встречает того самого монстра, на которого объявила охоту Красная королева, правительница Виль-Мажина. Новые друзья Эли — говорящий кот Бумер и ожившая машина Победа — готовы помочь ей остановить безумства Красной королевы и спасти монстра. Медлить нельзя, ведь через три дня портал закроется, и Эля рискует остаться в сказочной стране на всю жизнь. Удастся ли ей восстановить мир в Виль-Мажине и вернуться домой живой?', 'Каждый из нас обладает огромной силой, нужно лишь её найти', 6, '2023', 'повесть', false, false),
  (41, 'Глас земли', 'glas-zemli', 'glas-zemli.png', 'Древнее пророчество гласит, что нога, отделённая от тела, но наделённая самосознанием и мощной политической интуицией, ступит на землю и оставит глубокий след. И тот, кто минует сорок врат и на исходе дня склонится, чтобы обратить свой взор к отпечатку ступни на сырой земле, узрит доселе невиданное: сказавшую первое слово обезьяну и вырванное левреткой генеральское сердце, великого диктатора на деревянных протезах и вывернутого наизнанку лебедя, современного поэта в экстазе вдохновения и зубы крестьянина на горле ядовитого змия, старца в младенческой колыбели и светоносного ангела в стакане чёрного чая, философствующий кочан капусты и неисчислимые полчища плотоядных жужелиц, а за всем этим — нечто такое, что от начала времён сокрыто многослойной завесой непостижимости, но приемлет в себя каждого, кто бежит от него прочь: самое счастливое, сильное и справедливое государство на планете, дарующее страждущему человечеству священную науку скорби, смирения и сострадания.', 'Фланирование над&nbsp;оскаленной бездной', 18, '2023', 'сборник прозы', false, false),
  (42, 'Доктор Сакс', 'doctor-sax', 'doctor-sax.png', 'Воспоминания мальчика Джеки о похождениях с друзьями, гремящие бейсбольные матчи, беззаботные игры, которые он устраивает для себя самого, возводят безопасный мир детства. Однако сны Джеки, порой страшные, и мысли о потустороннем воплощаются в готическо-апокалиптическую фантазию: в таинственном Замке живут вампиры, гномы и колдуны, а Доктор Сакс борется со Змеем, олицетворяющим Мировое Зло. Сможет ли Доктор Сакс победить и провести грань между светом и тьмой? Джек Керуак написал «Доктора Сакса» в 1952 году, когда жил в Мехико в гостях у Уильяма Берроуза. По легенде, автор под воздействием наркотиков печатал свой роман на машинке в туалете, потому что другого места для работы не было. Эта легенда хорошо вписывает роман Керуака в контркультурную историю битников. При этом в романе вы обнаружите барочное по форме и автобиографическое в своей основе повествование о четырнадцатилетнем Джеке Дулуозе, о его родном Лоуэлле, семье, друзьях, детских и подростковых фантазиях, страхе смерти и его преодолении. Читатель при знакомстве с творчеством Керуака обращает внимание прежде всего на романы «В дороге» и «Бродяги Дхармы», упуская из виду, пожалуй, самую искреннюю, ритмичную и пророческую книгу автора — «Доктор Сакс». История о битве с Тьмой и спустя семьдесят лет после создания напоминает нам о необходимости посмотреть внутрь себя и столкнуться с личными страхами, чтобы победить змеев, угрожающих извне, и сохранить ценность человеческой жизни во времена, когда она становится наиболее&nbsp;хрупкой.', 'Вселенная исторгает собственное зло', 18, '2023', 'роман', false, false),
  (43, 'Бог его имя', 'bog-ego-imya', 'bog-ego-imya.jpg', 'Анна и Шмуэль знакомы с детства, и Анна верит, что он — тот, чьё имя ангел шепнул ей перед её рождением, что они предназначены друг другу; в то же время Шмуэль влюблён в сестру Анны. Чёрно-белая картина детства, где существуют правильные и неправильные поступки, вечная любовь и нерушимые обязательства, постепенно тает, сменяясь бытом взрослой жизни. Вечной любви нет места в этом мире, волшебство кончается. Или это неправда? «Это история взросления — не человека, а его чувств. История о том, как мы оправдываем выбор, который делаем в жизни», — пишет автор.', 'Взмах крыла голубя может изменить судьбу', 16, '2021', 'повесть', false, false),
  (44, 'Россия', 'rossia', 'rossia.png', 'Он просыпается среди ночи, потому что понимает: в квартире кто-то есть! Садится и начинает печатать на печальной машинке: «Я заперт в своей квартире, потому что до смерти боюсь собственного дерьма». А снаружи — зверь с ужасным оскалом, гопники и менты, ывли и — сплошная&nbsp;россия. Но рано или поздно ему придётся выйти в неё и стать корреспондентом, чтобы свидетельствовать: россия — это не Россия. В россии сосуществуют Создатель и Разрушитель, практик и теоретик, Вова, Володя, Владимир и Вован, агенты каждый день получают сводки в ларьках «Роспечать» и пьют воду-из-под-крана, которая поддерживает всеобщую непрерывную дремоту. Древний алгоритм В.О.В.А. заставляет Колесо вертеться, снова и снова разделяя всех на этих и тех, и только избранные умеют находить&nbsp;щели. При чтении возможны побочные эффекты: привыкание, головокружение, бессонница, паранойя, обострение шизофрении, суицидальные мысли, паническая боязнь собственного&nbsp;дерьма. Автор о книге: «Ритуал — это порядок обрядовых действий. Ритуал совершается там, где человеку нужно повлиять на действительность, сделать так, чтобы в бытии что-то стало, остановилось. Она ведь течёт, перекатывается, эта действительность, и если в ней удаётся поймать просветы счастья, понимания, знания — они тут же улетучиваются, растворяются в потоке. Ритуал — это форма, призванная поймать их и оставить при себе, сконструировать человеческое. „россия“ — это роман-ритуал, и история его создания — это история попыток остановиться, замереть и&nbsp;видеть. Конечно, это не остросоциальная, не политическая книга. Но бытие, как ни крути, исторично. Оно предстаёт перед нами в конкретных формах, и задача — не витать за их пределами, в чистых эмпиреях, а найти всё самое важное здесь и сейчас, во всей этой суматохе&nbsp;дней. И ещё. Перед прочтением книги я рекомендую начисто забыть, что есть граница между внутренним миром и внешним. Всё&nbsp;едино».', 'россия должна быть сплошной!', 18, '2023', 'роман-ритуал', false, false),
  (45, 'Овердрайв', 'overdrive', 'overdrive.jpg', 'Антироман рокера, борца за справедливость и психонавта, психоделически исчезнувшего сразу после публикации своего магнум опуса, успел стать культовым ещё в&nbsp;виде цифрового издания. Спустя годы после релиза цифровой версии мир дождался печатного издания. «Овердрайв» — это точка входа в мир, каким он открылся провинциальному юноше, переехавшему в Санкт-Петербург в поисках любви, возможности стать рок-звездой и&nbsp;разгадки тайны Великого Но (но&nbsp;тут, как всегда, начинается Всё Это). О том, как желаемое становится действительным, о зыбкой грани между реальностью и мифом, о&nbsp;великом гитарном баттле Эроса и Танатоса и&nbsp;о&nbsp;том, о чём не говорят вовсе. «Я люблю эту книгу и боюсь её. Её&nbsp;страницы населены всем самым лучшим, самым кошмарным и самым важным, что&nbsp;я&nbsp;сумел отыскать в себе, её текст высечен из камня. Я&nbsp;не&nbsp;представляю, что&nbsp;с&nbsp;вами будет, когда вы её прочитаете», — пишет автор.', 'Обратная сторона рока', 18, '2019', 'антироман', false, false),
  (46, 'Колми', 'kolmi-press', 'kolmi-press.jpg', 'КОЛМИ — это печатное СМИ, ивент-агентство и лейбл, представляющий художественные интересы передовых деятелей российского искусства. Сверхгазета бесплатно распространяется в самых козырных местах необъятной: если ты урвал экземпляр, то считай, что прожил квартал не&nbsp;зря. КОЛМИ создаёт команда петербургских самозванцев, выдающих себя за самопровозглашенцев, выдающих себя за деятелей культуры и искусств, да так правдоподобно, что настоящие их деятели и иные корифеи то и дело появляются в материалах газеты, в которую твои потомки завернут свою порцию&nbsp;скумбрии.', 'печатное издание нового времени', 18, '2023', 'сверхгазета', false, false),
  (47, 'Котлован', 'kotlovan', 'kotlovan.jpg', 'Рабочего Вощева увольняют с завода за слабосильность и задумчивость. Придя в другой город, он присоединяется к артели, которая роет котлован. На этом месте должен появиться общепролетарский дом. В проект здания постоянно вносят изменения, и котлован становится только шире и глубже. А рабочие, строящие светлое будущее, обречены на страдания. Повесть Андрея Платонова, написанная в 1930 году, похожа на антиутопию — только не о будущем, а о настоящем советских людей: в ней воспроизводятся страшные события и реалии коллективизации. Однако «Котлован» — ещё и философское произведение. Рабочие словно находятся в пространстве между жизнью и смертью, чувствуют безысходность — то ли от своей работы, то ли от своего существования. Главный герой Вощев — правдоискатель, отчаянно пытающийся найти смысл «природной жизни» и выпадающий из среды народных масс. Именно он задаёт «вечные» вопросы об истине и счастье. Издание дополняют карточки с портретами и характеристиками персонажей, а также исторические комментарии с фотоматериалами.', 'Работая над веществом жизни', 16, '2022', 'повесть', false, false),
  (48, 'А где же Слава?', 'slava', 'slava.png', 'Коммуналка, хрущёвка, Кремль и Вавилонская башня. Проза, поэзия и любовь. Люмпены, ветеран Афганской войны, принцесса, Достоевский и даже самая развитая во всей галактике форма жизни. Синдром чужой руки, миф о кесаревом сечении, инструкция по созданию голема и жуткий подарок Аполлона. Автор о книге: «Очень часто мне доводилось слышать, что я странный человек: не так думаю, не так шучу, невпопад смеюсь. Когда работал над этим сборником, вдруг понял: в нём, в его художественном пространстве, я чувствую себя абсолютно свободным, могу рассказывать, что угодно и как угодно. Эти истории подарили свободу мне, и я бы очень хотел, чтобы подарили её и читателям».', 'От Москвы до Рязани, от любви до каббалы', 18, '2022', 'сборник прозы', false, false),
  (49, 'Двойник', 'dostoevski-dvoinik', 'dostoevski-dvoinik.png', 'Яков Петрович Голядкин — робкий, одинокий, обидчивый титулярный советник, чувствующий презрение своих коллег и желающий любви и уважения. Однажды он приезжает к статскому советнику Олсуфию Ивановичу Берендееву на бал в честь дня рождения его дочери Клары Олсуфьевны — возлюбленной Голядкина. Однако героя выдворяют. В минуты отчаяния он встречает своего двойника, который становится его врагом. В повести «Двойник», написанной в 1846 году, Фёдор Достоевский словно ведёт диалог с Николаем Гоголем. Художественный мир «Петербургской поэмы» связан с художественным миром гоголевской петербургской повести «Записки сумасшедшего»: в ней так же, как и в «Двойнике», затрагиваются тема борьбы бедного и богатого чиновников за сердце дочери начальника и тема безумия. Голядкин не только «маленький человек» — этот тип героя хорошо показан в другой повести Гоголя «Шинель», — но и человек, низведённый чиновничьим обществом до состояния «ветошки», впрочем, «ветошки», имеющей амбиции. Двойник Голядкина — это жуткий образ, рождённый отчуждённостью, нереализованными амбициями главного героя, разрушающий его жизнь и похищающий его личность. Динамично, фантасмагорично, трагично — именно так можно описать эту повесть.', 'Сходство разительное, обстоятельство странное, комедия пасквильная', 16, '2022', 'повесть', false, false),
  (50, 'Пожниночь', 'pozhninoch', 'pozhninoch.png', 'Рассказы, не вошедшие в сборник «Посейдень» , с которого началось издательство Чтиво, а также стихотворения, переводы и последние ночные посты Сергея Иннера — специальный проект Чтива к трёхлетию психоделического исчезновения автора. Вновь истории, рок-н-ролл, бесконечность, странствия в пространстве и сознании, а также Эрос, Танатос, агенты ФСБ, величайший торговец в истории, сама Литература, явившаяся в бар в облике соблазнительной красотки, и единственная причина отказаться от ночи с двумя раскрепощёнными девушками — держись, читатель!', 'Жизнь, любовь да нейросети', 18, '2022', 'сборник рассказов', false, false),
  (51, 'Достоевские дни', 'dostoevskie_dni', 'dostoevskie_dni.jpg', 'Писатель Фёдор Достоевский ест, спит, живёт и пишет великие книги. Найдёныш ищет друга, но не просто друга, а на всю жизнь. События разворачиваются в едином временном поле, где запросто соседствуют Достоевский, избранный автором в качестве своего альтер эго, Иван Тургенев, Юрий Трифонов, Борис Рыжий и — современность, в которой действует, если говорить словами Маяковского, «мастерская человечьих воскрешений».', 'Поэзия, доставленная в город на Неве', 18, '2022', 'роман', false, false),
  (52, 'Проститутки на обочине', 'prostitutes', 'prostitutes.jpg', 'Когда перевод этой книги попал к нам в редакцию, мы приняли его за очередную имитацию (хотя и довольно качественную) стиля Буковски, Хемингуэя, парижской прозы Генри Миллера etc. В сети почти не нашлось информации, которая подтверждала бы существование заявленного автора. Однако, копнув глубже, мы убедились, что Эрих фон Нефф действительно существует, имеет публикации в США и Европе, недавно ему исполнилось 80 лет, и он вышел на пенсию, а до тех пор работал докером в порту Окленда (Калифорния). Тогда-то мы взглянули на книгу совсем другими глазами. Действие рассказов происходит на прибрежных шоссе и в борделях Калифорнии и Техаса, в берлинском варьете, в флорентийском театре. Это истории о странных встречах и мимолётных отношениях, в которые вступает герой, странствуя по миру. Книга впервые издана в 1999 году на французском языке под названием ‘Prostitutees au Bord de La Route’ (издательство Сahiers de Nuit). Мы рады представить вам её первое русскоязычное издание.', 'Записки докера из Калифорнии', 18, '2019', 'Сборник рассказов', false, false),
  (53, 'Мир цвета сепии', 'sepiya', 'sepiya.jpg', 'Ленинградский художник Дмитрий Дьяконов тяжело переживает смерть родителей. Его также тяготят творческие неудачи и запутанные отношения с девушкой Аней, которую завлекли в эзотерическую общину. Тревожит его и набирающий силу кризис в стране — завершающий этап «перестройки». Ко всем бедам Дьяконова прибавляется основанное на оговоре обвинение в убийстве. Избежав ареста, он отправляется в глубинку, на поиски общины. Жизнь в роли беглого преступника заставляет его многое переосмыслить и взглянуть на мир по-новому.', 'Понять себя, чтобы не застрять на перепутье', 18, '2022', 'роман', false, false),
  (54, 'Воскресные призраки', 'prizraki', 'prizraki.jpg', 'Ирина, Дина и Марк — волонтёры, которые регулярно посещают хоспис с умирающими детьми, чтобы искупить боль, которую причиняли другим. Лариса мечтает сбежать от матери и её ухажёров, а её одноклассница Лиза смертельно больна. Муж Светланы избивает и жену, и дочь, и те сбегают от него в лес, прямо в лапы другого, настоящего зверя. Глеб подрабатывает таксистом, когда его нанимает Зара — солистка музыкальной группы; он находит в девушке новую жизнь и решает рассказать ей о своих секретах. В сборнике представлено двенадцать историй об одиночестве и чувстве вины, прощении и ненависти, травмах и поиске лекарства от неутихающей боли. О том, что какими бы путями ни шли герои, в конце они всё равно остаются наедине со своей совестью. И этот финальный диалог — самое тяжёлое испытание из возможных. Больше никаких иллюзий. Один на один.', 'Нельзя убежать от себя и с собой остаться невозможно', 18, '2022', 'сборник рассказов', false, false),
  (55, 'Ирокез', 'irokez', 'irokez.jpg', 'Не столь давняя история оживает, и современность играет новыми гранями: Ленин встречается с омоновцами, воспоминания провинциального детства обрываются вместе с жизнью старого пса, любовь рождается на стройплощадке и умирает в студенческой тетради, а преступлением может оказаться не только причёска, но и трезвость. Это рассказы о хрупкости и ценности человеческой жизни, которую люди готовы разменять на пачку купюр или корм для псов. Сердцевина книги — искренняя, напряжённая проза, обострённая чувствительность к тому, мимо чего многие пройдут, не задумываясь.', 'БЫСТРО И СТРАННО', 18, '2021', 'сборник рассказов', false, false),
  (56, 'Крафт', 'craft', 'craft.jpg', 'Две разных судьбы одного и того же человека пересекаются в одном микрорайоне. Офисный сотрудник проводит жизнь в размышлениях о смерти, а порой ему кажется, что он уже мёртв. Группа журналистов отправляется в пресс-тур в загадочный закрытый город; приехав на место, они понимают, что тур заказан только в один конец. Георгий Панкратов мастерски сплетает современные реалии с мирозданческими материями и экзистенциальными ужасами, способными привести в трепет даже самого бывалого читателя. Встречайте новые истории от автора «Российского времени» . Автор о книге: «На какие-то моменты современная литература обращает мало внимания, и хочу, чтобы они были представлены и услышаны. Меня волнуют несправедливость, сложности взаимопонимания между людьми, поиск счастья, который порою приводит их на достаточно странные территории, подталкивает к спорным решениям».', 'Любовь, смерть и каштаны', 18, '2021', 'сборник повестей', false, false),
  (57, 'Подземные', 'podzemnie', 'podzemnie.jpg', 'История любви одного из величайших писателей ХХ века к темнокожей девушке, опередившей своё время на несколько десятилетий, разворачивается перед нами в ритме спонтанной прозы на фоне гремящих тусовок бит-поколения в Сан-Франциско пятидесятых.', 'И ГАСНЕТ СВЕТ', 18, '2021', 'роман', false, false),
  (58, 'Белый цветок', 'white-flower', 'white-flower.jpg', 'Способна ли новая философия остановить тайное общество? Подземные реакторы вышли из-под контроля и грозят городу уничтожением. Нити заговора тянутся во дворец губернатора. Африканский посол инкогнито пробирается на священную литургию, но погибает от рук разъярённой толпы. Пассажиры автобуса обнаруживают в карманах записки странного содержания. Напитки отравлены наркотическим ядом. Человеческая кровь изливается в систему отопления. Сможет ли главный герой добраться до истины, прежде чем редкий мистический дар разрушит его сознание?', 'Жизнь соткана из чудес. Смерть — лишь одно из них', 18, '2019', 'Роман', false, false),
  (59, 'Смерти нет', 'smerti-net', 'smerti-net.jpg', 'Жители города пытаются укрыться от жизненных неурядиц на кладбище, где находят работу и кров. Судьба сталкивает здесь скульптора и бездомного, музыканта и убийцу, калеку и чемпиона. Однако по обе стороны кладбищенского забора человек имеет одни и те же слабости и пороки. Ни водка, ни колдовство, ни попытки найти смысл бытия не могут оградить героев от зла. Над ложью, подлостью и жаждой наживы их возвышают лишь любовь и смерть.', 'Поняв смерть, поймёшь и жизнь', NULL, '2021', 'роман', false, false),
  (60, 'Фрида и Гитта', 'frieda-and-gitta', 'frieda-and-gitta.jpg', 'Две отчаянные красотки Фрида и Гитта были участницами французского Сопротивления во время Второй мировой войны, а затем стали инспекторами парижской полиции. Ни время ни пространство не помешают им выследить преступников и заставить злодеев понести заслуженную кару. Слышите звонкий стук каблуков? Это приближается неотвратимое возмездие!', 'Правосудие на высоких каблуках', 18, '2020', 'сборник прозы', false, false),
  (61, 'Люцифер', 'lucifer', 'lucifer.jpg', 'Божий сын, рождённый земной женщиной, сегодня суперзвезда, но — много ли мы знаем о первом сыне Бога, рождённом Светоносной Материей, Великой Матерью Мира — Люцидой?', 'Несущий свет не станет тьмой', 16, '2020', 'Поэма', false, false),
  (62, 'В Дороге', 'v-doroge', 'v-doroge.jpg', 'Один из величайших романов XX века в новом переводе, соответствующем поэтической и ритмической прозе Керуака. Это совершенно не похоже на то, что вы читали раньше, вас ждёт невероятный кайф, великий джаз безумных мастеров бибопа и путешествия через «просторы старой рухнувшей Святой Америки от устья до устья и от края до края». Поехали!', 'ТЫ НА ПУТИ К НЕБЕСАМ', 18, '2020', 'Роман', false, false),
  (63, 'ПРЕПОДРОБНЫЙ. БЫТИЕ СЕРГЕЯ ИННЕРА', 'prepodrobniy', 'prepodrobniy.jpg', 'Попытка собрать воедино все имеющиеся данные о рок-певце, писателе, любовнике, борце за справедливость, психонавте, путешественнике и мыслителе, авторе антиромана «Овердрайв» и основателе издательства «Чтиво», ушедшем от нас слишком рано и неизвестно куда.', 'ОН УСТАЛ БЫТЬ ПОСЛОМ РОК-Н-РОЛЛА В&nbsp;НЕРИТМИЧНОЙ&nbsp;СТРАНЕ', 18, '2020', 'бытие', false, false),
  (64, 'Мы Кому То Нужны', 'my-komu-to-nujni', 'my-komu-to-nujni.jpg', 'Жители затерянной на краю Земли деревушки во время наводнения оказываются отрезанными от большого мира. Река затапливает дома и подбирается к самому дальнему, где живет Валентина. Ей и деверю Варламу теперь нужно придумать план спасения. Это непросто: идти некуда. А ещё у них на руках тело мужа Валентины, скончавшегося накануне паводка. Один на один со стихией героям приходится найти в себе силы не пасть духом и бороться за то, что ещё осталось.', 'Конец света на краю Земли', 16, '2019', 'Роман', false, false);
